"use client";

import React, {
  useState,
  useEffect,
  useMemo,
  useCallback,
  useContext,
} from "react";
import { Link } from "react-router-dom";
import { FiEdit2, FiTrash2 } from "react-icons/fi";

import { AgGridReact } from "ag-grid-react";
import {
  AllCommunityModule,
  ModuleRegistry,
  themeQuartz,
  iconSetQuartzLight,
} from "ag-grid-community";

import dayjs from "dayjs";

import AddSiteDialog from "./AddSite/SitesAddDialog";
import DeleteDialog from "./ActionButton/DeleteDialog";
import EditDialog from "./ActionButton/EditDialog";

import { AuthContext } from "../../../../context/AuthContext";
import { API } from "../../../../lib/endpoint";
import { GET } from "../../../../lib/request";

import "ag-grid-community/styles/ag-grid.css";
// import "ag-grid-community/styles/ag-theme-quartz.css";

ModuleRegistry.registerModules([AllCommunityModule]);

export default function Sites() {
  const [sites, setSites] = useState([]);
  const auth = useContext(AuthContext);
  const [isDarkMode] = useState(false);
  const [editRow, setEditRow] = useState(null);
  const [deleteId, setDeleteId] = useState(null);

  // Fetch Sites
  const getnumberOfSite = async () => {
    try {
      const res = await GET(API.SITE.COUNT);
      setSites(res?.msg || []);
    } catch (error) {
      console.error(error);
      setSites([]);
    }
  };

  useEffect(() => {
    getnumberOfSite();
  }, []);

  // AG Grid Theme
  const myTheme = themeQuartz.withPart(iconSetQuartzLight).withParams({
    browserColorScheme: isDarkMode ? "dark" : "light",
    fontFamily: { googleFont: "Outfit" },
    headerFontSize: 15,
    fontSize: 14,
    backgroundColor: isDarkMode ? "#111827" : "#ffffff", // ← updated to match dark:bg-gray-900
    headerBackgroundColor: isDarkMode ? "#181D2E" : "#D1CDCD",
    oddRowBackgroundColor: isDarkMode ? "#2d3748" : "#fafbfc",
    // rowBorder: true,
    // borderColor: isDarkMode ? "#4b5563" : "#e2e8f0",
    headerTextColor: isDarkMode ? "#D1CDCD" : "#374151",
    foregroundColor: isDarkMode ? "#e5e7eb" : "#374151",
    accentColor: "#6366f1",
    headerHeight: 48,
    rowHeight: 50,
  });

  // Row Data
  const rowData = useMemo(() => {
    return sites.map((site, index) => ({
      sno: index + 1,
      id: site._id,
      uid: site.uid,
      siteName: site.siteName,
      location: site.location,
      deviceCount: site.deviceCount,
      createdAt: dayjs(site.createdAt).format("DD MMM YYYY"),
      fullData: site,
    }));
  }, [sites]);

  // Link Renderer
  const linkRenderer = useCallback((params) => {
    return (
      <Link
        to="/sites-profile"
        state={params.data.fullData}
        style={{
          color: "#4da8da",
          fontWeight: "600",
          textDecoration: "none",
        }}
      >
        {params.value}
      </Link>
    );
  }, []);

  // Action Renderer
  const actionRenderer = useCallback(
    (params) => {
      if (auth?.user?.role !== "admin") return null;

      return (
        <div className="flex items-center gap-3">
          {/* Edit */}
          <button
            onClick={() => setEditRow(params.data.fullData)}
            className="p-2 rounded-md text-blue-600 hover:bg-blue-50 hover:text-blue-700 transition"
            title="Edit Site"
          >
            <FiEdit2 size={16} />
          </button>

          {/* Delete */}
          <button
            onClick={() => setDeleteId(params.data.id)}
            className="p-2 rounded-md text-red-600 hover:bg-red-50 hover:text-red-700 transition"
            title="Delete Site"
          >
            <FiTrash2 size={16} />
          </button>
        </div>
      );
    },
    [auth?.user?.role],
  );

  // Columns
  const colDefs = useMemo(() => {
    const cols = [
      { field: "sno", headerName: "S.No", maxWidth: 80 },

      {
        field: "uid",
        headerName: "UID",
        cellRenderer: linkRenderer,
        minWidth: 80,
      },

      {
        field: "siteName",
        headerName: "Site Name",
        cellRenderer: linkRenderer,
        minWidth: 80,
      },

      {
        field: "location",
        headerName: "Location",
        minWidth: 80,
      },

      {
        field: "deviceCount",
        headerName: "Devices",
        minWidth: 80,
      },

      {
        field: "createdAt",
        headerName: "Added On",
        minWidth: 80,
      },
    ];

    if (auth?.user?.role === "admin") {
      cols.push({
        headerName: "Action",
        cellRenderer: actionRenderer,
        minWidth: 220,
        // pinned: "right",
      });
    }

    return cols;
  }, [actionRenderer, auth.user.role, linkRenderer]);

  const defaultColDef = {
    sortable: true,
    filter: true,
    resizable: true,
    flex: 1, // auto grow
    minWidth: 100,
    headerClass: "custom-header",
    cellClass: "custom-cell",
  };

  return (
    <div className="p-6 bg-slate-100 min-h-screen">
      {/* Breadcrumb */}
      <nav className="mb-4 text-sm">
        <Link to="/dashboard" className="text-sky-500 font-medium no-underline">
          Dashboard
        </Link>

        <span className="mx-2">›</span>

        <span className="text-[#0f3057] font-semibold">
          Site Command Center
        </span>
      </nav>

      {/* Header */}
      <div className="bg-gradient-to-br from-[#0a192f] to-[#0f3057] rounded-xl p-5 mb-5 flex justify-between items-center shadow-[0_8px_24px_rgba(0,0,0,0.25)]">
        <h2 className="text-white m-0 text-xl font-semibold">
          SITE COMMAND CENTER
        </h2>

        <div className="flex gap-4 items-center">
          <span className="text-white font-medium">
            {sites?.length || 0} Sites
          </span>

          {auth?.user?.role === "admin" && (
            <AddSiteDialog getnumberOfSite={getnumberOfSite} buttonClass="px-5 py-2 
       bg-transparent
       border border-white-900
       text-white text-sm font-semibold bg-blue-800
       rounded-lg
       transition-all duration-200
       hover:bg-blue-900 hover:text-white" />
          )}
        </div>
      </div>

      {/* Grid Panel */}
      <div className="bg-white rounded-2xl shadow-lg border border-gray-200">
        {/* Panel Header */}
        <div className="px-6 py-4 border-b border-gray-200 flex justify-between items-center">
          <h3 className="font-semibold text-xl text-[#0f3057]">
            Active Site List
          </h3>
        </div>

        {/* Grid Wrapper */}
        <div className="w-full">
          {/* Horizontal Scroll Wrapper */}
          <div className="overflow-x-auto">
            <div
              className="ag-theme-quartz"
              style={{
                minWidth: "1100px", // ensures scroll if columns overflow
                height: "500px",
              }}
            >
              <AgGridReact
                theme={myTheme}
                rowData={rowData}
                columnDefs={colDefs}
                defaultColDef={defaultColDef}
                pagination={true}
                paginationPageSize={10}
                paginationPageSizeSelector={[10, 20, 50, 100]}
                rowSelection="multiple"
                animateRows={true}
                suppressMenuHide={true}
                onGridReady={(params) => {
                  params.api.sizeColumnsToFit();
                }}
              />
            </div>
          </div>
        </div>
      </div>
      {editRow && (
        <EditDialog
          row={editRow}
          sitesID={editRow._id}
          getnumberOfSite={getnumberOfSite}
          onClose={() => setEditRow(null)}
        />
      )}

      {deleteId && (
        <DeleteDialog
          sitesID={deleteId}
          getnumberOfSite={getnumberOfSite}
          onClose={() => setDeleteId(null)}
        />
      )}
    </div>
  );
}
