"use client";

import React, { useState, useEffect, useMemo } from "react";
import { Link } from "react-router-dom";

import { AgGridReact } from "ag-grid-react";
import {
  AllCommunityModule,
  ModuleRegistry,
  themeQuartz,
  iconSetQuartzLight,
} from "ag-grid-community";

import { API } from "../../../lib/endpoint";
import { GET } from "../../../lib/request";
import NodataFound from "../../../assets/img/nodatafound.png";

import "ag-grid-community/styles/ag-grid.css";

ModuleRegistry.registerModules([AllCommunityModule]);

export default function Resistance() {
  const [resistance, setResistance] = useState([]);
  const [isDarkMode] = useState(false);

  // ================= FETCH DATA =================
  const getAllSiteResistance = async () => {
    try {
      const res = await GET(API.SITE.ALL_RESISTANCE);
      setResistance(res?.msg || []);
    } catch (error) {
      console.error(error);
      setResistance([]);
    }
  };

  useEffect(() => {
    getAllSiteResistance();

    const interval = setInterval(() => {
      getAllSiteResistance();
    }, 20000);

    return () => clearInterval(interval);
  }, []);

  // ================= THEME =================
  const myTheme = themeQuartz.withPart(iconSetQuartzLight).withParams({
    browserColorScheme: isDarkMode ? "dark" : "light",
    fontFamily: { googleFont: "Outfit" },
    headerFontSize: 15,
    fontSize: 14,
    backgroundColor: isDarkMode ? "#111827" : "#ffffff",
    headerBackgroundColor: isDarkMode ? "#181D2E" : "#D1CDCD",
    oddRowBackgroundColor: isDarkMode ? "#2d3748" : "#fafbfc",
    headerTextColor: isDarkMode ? "#D1CDCD" : "#374151",
    foregroundColor: isDarkMode ? "#e5e7eb" : "#374151",
    accentColor: "#6366f1",
    headerHeight: 48,
    rowHeight: 50,
  });

  // ================= ROW DATA =================
  const rowData = useMemo(() => {
    return resistance.map((row, index) => ({
      sno: index + 1,
      siteUid: row?.siteId?.[0]?.uid || "-",
      siteName: row?.siteId?.[0]?.siteName || "-",
      deviceUid: row?.nodeUid || "-",
      deviceName: row?.deviceName || "-",
      resistanceUid: row?.resistanceNumber || "-",
      resistanceValue: row?.resistanceValue || "-",
      threshold: row?.resSensorsThreshold || 0,
    }));
  }, [resistance]);

  // ================= COLUMNS =================
  const colDefs = useMemo(
    () => [
      { field: "sno", headerName: "S.No", maxWidth: 80 },

      { field: "siteUid", headerName: "Site UID" },

      { field: "siteName", headerName: "Site Name" },

      { field: "deviceUid", headerName: "Device UID" },

      { field: "deviceName", headerName: "Device Name" },

      { field: "resistanceUid", headerName: "Resistance UID" },

      {
        field: "resistanceValue",
        headerName: "Resistance Value",
        cellClassRules: {
          "bg-red-200 text-red-700 font-semibold": (params) =>
            params.data.resistanceValue > params.data.threshold,
        },
      },
    ],
    [],
  );

  const defaultColDef = {
    sortable: true,
    filter: true,
    resizable: true,
    flex: 1,
    minWidth: 120,
  };

  return (
    <div className="p-6 bg-slate-100 min-h-screen">
      
      {/* Breadcrumb */}
      <nav className="mb-4 text-sm">
        <Link to="/dashboard" className="text-sky-500 font-medium no-underline">
          Dashboard
        </Link>

        <span className="mx-2">›</span>

        <span className="text-[#0f3057] font-semibold">
          Resistance Monitoring
        </span>
      </nav>

      {/* HEADER PANEL */}
      <div className="bg-gradient-to-br from-[#0a192f] to-[#0f3057] rounded-xl p-5 mb-5 flex justify-between items-center shadow-[0_8px_24px_rgba(0,0,0,0.25)]">
        <h2 className="text-white text-xl font-semibold m-0">
          RESISTANCE MONITORING
        </h2>

        <span className="text-white font-medium">
          {resistance?.length || 0} Sensors
        </span>
      </div>

      {/* GRID PANEL */}
      <div className="bg-white rounded-2xl shadow-lg border border-gray-200">
        {/* Panel Header */}
        <div className="px-6 py-4 border-b border-gray-200 flex justify-between items-center">
          <h3 className="font-semibold text-xl text-[#0f3057]">
            Active Resistance Devices
          </h3>
        </div>

        {/* Grid */}
        {rowData.length > 0 ? (
          <div className="overflow-x-auto">
            <div
              className="ag-theme-quartz"
              style={{
                minWidth: "1100px",
                height: "500px",
              }}
            >
              <AgGridReact
                theme={myTheme}
                rowData={rowData}
                columnDefs={colDefs}
                defaultColDef={defaultColDef}
                pagination={true}
                paginationPageSize={10}
                paginationPageSizeSelector={[10, 20, 50, 100]}
                animateRows={true}
                suppressMenuHide={true}
                onGridReady={(params) => {
                  params.api.sizeColumnsToFit();
                }}
              />
            </div>
          </div>
        ) : (
          <div className="flex flex-col items-center justify-center h-[60vh]">
            <img src={NodataFound} alt="No Data" className="w-40 opacity-80" />
            <p className="mt-4 text-blue-500 font-medium">No Device Found</p>
          </div>
        )}
      </div>
    </div>
  );
}
