"use client";

import React, { useState, useEffect, useMemo, useCallback } from "react";
import { AgGridReact } from "ag-grid-react";
import {
  AllCommunityModule,
  ModuleRegistry,
  themeQuartz,
  iconSetQuartzLight,
} from "ag-grid-community";

import dayjs from "dayjs";
import { AiOutlineSearch } from "react-icons/ai";
import { IoClose } from "react-icons/io5";

import axiosInstance from "../../../api/axiosInstance";
import DeleteDialog from "./DeleteAlarm";
import NodataFound from "../../../assets/img/nodatafound.png";

import "ag-grid-community/styles/ag-grid.css";

ModuleRegistry.registerModules([AllCommunityModule]);

export default function Alarm() {
  const [alarm, setAlarm] = useState([]);
  const [total, setTotal] = useState(0);
  const [searchTerm, setSearchTerm] = useState("");

  // ================= FETCH ALARM DATA =================
  const getAllAlarm = useCallback(async () => {
    try {
      const response = await axiosInstance.get("/api/alarm/getAlarmData", {
        params: {
          search: searchTerm || null,
          startDate: dayjs("2023-01-01").format("YYYY-MM-DD"),
          endDate: dayjs("2030-01-01").format("YYYY-MM-DD"),
        },
      });

      setAlarm(response?.data?.data || []);
      setTotal(response?.data?.lengthData || 0);
    } catch (error) {
      console.error("Alarm fetch error:", error);
    }
  }, [searchTerm]);

  // search change
  useEffect(() => {
    getAllAlarm();
  }, [getAllAlarm]);

  // auto refresh
  useEffect(() => {
    const interval = setInterval(() => {
      getAllAlarm();
    }, 10000);

    return () => clearInterval(interval);
  }, [getAllAlarm]);

  // ================= AG GRID THEME =================
  const myTheme = themeQuartz.withPart(iconSetQuartzLight).withParams({
    fontFamily: { googleFont: "Outfit" },
    headerFontSize: 15,
    fontSize: 14,
    headerBackgroundColor: "#D1CDCD",
    oddRowBackgroundColor: "#fafbfc",
    headerHeight: 48,
    rowHeight: 50,
  });

  // ================= ROW DATA =================
  const rowData = useMemo(() => {
    return alarm.map((row, index) => ({
      sno: index + 1,
      siteUid: row?.deviceId?.siteId?.uid || "-",
      siteName: row?.deviceId?.siteId?.siteName || "-",
      deviceUid: row?.deviceId?.nodeUid || "-",
      deviceName: row?.deviceId?.deviceName || "-",
      sensor: row?.SensorName || "-",
      threshold: row?.thresholdValue || "-",
      alarmValue: row?.alarmValue || "-",
      time: dayjs(row?.createdAt).format("h:mm A"),
      date: dayjs(row?.createdAt).format("DD-MM-YYYY"),
      id: row?._id,
    }));
  }, [alarm]);

  // ================= TABLE COLUMNS =================
  const colDefs = [
    { field: "sno", headerName: "S.No", maxWidth: 80 },

    { field: "siteUid", headerName: "Site UID" },

    { field: "siteName", headerName: "Site Name" },

    { field: "deviceUid", headerName: "Device UID" },

    { field: "deviceName", headerName: "Device Name" },

    { field: "sensor", headerName: "Sensor Name" },

    { field: "threshold", headerName: "Threshold Value" },

    {
      field: "alarmValue",
      headerName: "Alarm Value",
      cellClass: "text-red-600 font-semibold",
    },

    { field: "time", headerName: "Time" },

    { field: "date", headerName: "Date" },

    {
      headerName: "Action",
      minWidth: 120,
      cellRenderer: (params) => (
        <DeleteDialog alarmID={params.data.id} getnumberOfAlarm={getAllAlarm} />
      ),
    },
  ];

  const defaultColDef = {
    sortable: true,
    filter: true,
    resizable: true,
    flex: 1,
    minWidth: 120,
  };

  return (
    <div className="w-full min-h-screen bg-slate-100 p-4 md:p-6">
      {/* HEADER PANEL */}
      <div
        className="bg-gradient-to-br from-[#0a192f] to-[#0f3057]
        rounded-xl p-4 md:p-5 mb-6
        flex flex-col md:flex-row md:items-center md:justify-between
        gap-3 shadow-lg"
      >
        <h2 className="text-white text-lg md:text-xl font-semibold">
          ALARM MONITORING
        </h2>

        <span className="text-white text-sm md:text-base font-medium">
          {total} Alarms
        </span>
      </div>

      {/* PANEL */}
      <div className="bg-white rounded-2xl shadow-md border border-gray-200 overflow-hidden">
        {/* PANEL HEADER */}
        <div
          className="px-4 md:px-6 py-4 border-b border-gray-200
          flex flex-col md:flex-row md:items-center md:justify-between gap-4"
        >
          <h3 className="font-semibold text-lg text-[#0f3057]">
            Active Alarm List
          </h3>

          {/* SEARCH */}
          <div className="relative w-full md:w-80">
            <AiOutlineSearch className="absolute left-3 top-2.5 text-gray-500" />

            <input
              type="text"
              placeholder="Search UID / Name"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-9 pr-8 py-2 border rounded-lg
              focus:outline-none focus:ring-2 focus:ring-blue-500"
            />

            {searchTerm && (
              <IoClose
                className="absolute right-2 top-2.5 cursor-pointer text-gray-500"
                onClick={() => setSearchTerm("")}
              />
            )}
          </div>
        </div>

        {/* GRID */}
        {rowData.length > 0 ? (
          <div className="w-full overflow-x-auto">
            <div
              className="ag-theme-quartz w-full"
              style={{
                height: "520px",
                minWidth: "1000px",
              }}
            >
              <AgGridReact
                theme={myTheme}
                rowData={rowData}
                columnDefs={colDefs}
                defaultColDef={defaultColDef}
                pagination={true}
                paginationPageSize={10}
                paginationPageSizeSelector={[10, 20, 50, 100]}
                animateRows={true}
                suppressMenuHide={true}
              />
            </div>
          </div>
        ) : (
          <div className="flex flex-col items-center justify-center h-[60vh]">
            <img src={NodataFound} alt="No Data" className="w-40 opacity-80" />
            <p className="mt-4 text-blue-500 font-medium">No Alarm Found</p>
          </div>
        )}
      </div>
    </div>
  );
}
