import React, { useCallback, useEffect, useMemo, useState } from "react";
import {
  Grid,
  Typography,
  FormControl,
  MenuItem,
  TextField,
} from "@mui/material";
import { Line } from "react-chartjs-2";
import { AdapterDateFns } from "@mui/x-date-pickers/AdapterDateFns";
import { LocalizationProvider } from "@mui/x-date-pickers/LocalizationProvider";
import { DesktopDatePicker } from "@mui/x-date-pickers/DesktopDatePicker";
import moment from "moment";
import DewnloadReport from "../../../DownloadReport/Downlaod";
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend,
} from "chart.js";
import dayjs from "dayjs";
import { AuthContext } from "../../../../../context/AuthContext";
import hondaGif from "../../../../../assets/img/hondagif.gif";
import { API } from "../../../../../lib/endpoint";

import { POST } from "../../../../../lib/request";
ChartJS.register(
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend,
);
const getTempValue = (row) =>
  Number(
    row?.msg?.TempValues?.DATASTREAMS?.[0]?.value ??
      row?.msg?.DATASTREAMS?.[0]?.value ??
      row?.temp ??
      0,
  );

const getHumValue = (row) =>
  Number(
    row?.msg?.HumValues?.DATASTREAMS?.[0]?.value ??
      row?.msg?.DATASTREAMS?.[0]?.value ??
      row?.humidity ??
      0,
  );
export const options = {
  responsive: true,
  plugins: {
    legend: {
      position: "top",
    },
    title: {
      display: true,
    },
  },
};

export default function Graph({
  device,
  sensor,
  SensorTypeChange,
  intervalId,
  value,
}) {
  const auth = React.useContext(AuthContext);
  const currentDate = dayjs().toDate();

  const [dateType] = useState(0);

  const [startDate, setStartDate] = useState(
    moment(new Date()).format("YYYY-MM-DD"),
  );

  const handleData = (data, datatype) => {
    if (datatype === "startDate") {
      setStartDate(moment(data).format("YYYY-MM-DD"));
    }
  };
  const [phasevalue, setPhaseValue] = useState(1);
  const PhaseValueChange = (newValue) => {
    setPhaseValue(newValue);
  };

  // ==================================================== //
  const [labels, setLabels] = React.useState([]);
  const [graphData, setGraphData] = React.useState([]);
  const [DataSets, setDataSets] = React.useState([]);
  const [borderColorArray] = React.useState([
    "rgb(255, 99, 132)",
    "rgb(230, 230, 0)",
    "rgb(51, 204, 255)",
    "rgb(204, 51, 255)",
    "rgb(60, 179, 113)",
    "rgb(238, 130, 238)",
    "rgb(255, 165, 0)",
    "rgb(106, 90, 20)",
    "rgb(255, 99, 71)",
  ]);
  const [backgroundColorArray] = React.useState([
    "rgba(255, 99, 132, 0.5)",
    "rgba(230, 230, 0, 0.5)",
    "rgba(51, 204, 255, 0.5)",
    "rgba(0, 0, 255, 0.5)",
    "rgba(60, 179, 113, 0.5)",
    "rgba(238, 130, 238, 0.5)",
    "rgba(255, 165, 0, 0.5)",
    "rgba(106, 90, 205, 0.5)",
    "rgba(255, 99, 71, 0.5)",
  ]);

  const [ItemPhase] = React.useState(["R", "Y", "B", "RY", "YB", "RB"]);

  const [userDevice, setUserDevice] = React.useState([]);

  useEffect(() => {
    const ds = auth?.user?.deviceSensors;
    if (!Array.isArray(ds) || !device?._id) return;
    const found = ds.find((item) => item.deviceId === device._id);
    setUserDevice(found);
  }, [auth, device?._id]);

  const computedDataSets = useMemo(() => {
    if (!Array.isArray(graphData) || graphData.length === 0) return [];

    const role = auth?.user?.role;

    if (sensor === "RES") {
      const count =
        role === "user"
          ? userDevice?.resistanceNumber?.length || 0
          : Number(device?.resSensors || 0);
      return Array.from({ length: count }, (_, i) => ({
        label: `R${i + 1}`,
        data: graphData.map((item) => item?.msg?.DATASTREAMS?.[i]?.value),
        borderColor: borderColorArray[i],
        backgroundColor: backgroundColorArray[i],
      }));
    }

    if (sensor === "SPD") {
      const count =
        role === "user"
          ? userDevice?.spdNumber?.length || 0
          : Number(device?.spdSensors || 0);
      return Array.from({ length: count }, (_, i) => ({
        label: `SPD${i + 1}`,
        data: graphData.map((item) => item?.msg?.DATASTREAMS?.[i]?.value),
        borderColor: borderColorArray[i],
        backgroundColor: backgroundColorArray[i],
      }));
    }

    if (sensor === "NER") {
      const count =
        role === "user"
          ? userDevice?.gnNumber?.length || 0
          : Number(device?.nerSensors || 0);
      return Array.from({ length: count }, (_, i) => ({
        label: `GN${i + 1}`,
        data: graphData.map((item) => item?.msg?.DATASTREAMS?.[i]?.value),
        borderColor: borderColorArray[i],
        backgroundColor: backgroundColorArray[i],
      }));
    }

    if (sensor === "VMR") {
      const phases =
        role === "user" && Array.isArray(userDevice?.phaseNumber)
          ? ItemPhase.slice(0, userDevice.phaseNumber.length)
          : ItemPhase;
      return phases.map((phase, i) => ({
        label: phase,
        data: graphData
          .filter((item) => item?.phaseNumber === phase.toLowerCase())
          .map((item) => item?.value),
        borderColor: borderColorArray[i],
        backgroundColor: backgroundColorArray[i],
      }));
    }

    if (sensor === "TEMP") {
      return [
        {
          label: "T1",
          data: graphData.map((item) => getTempValue(item)),
          borderColor: borderColorArray[0],
          backgroundColor: backgroundColorArray[0],
        },
      ];
    }

    if (sensor === "HUM") {
      return [
        {
          label: "H1",
          data: graphData.map((item) => getHumValue(item)),
          borderColor: borderColorArray[0],
          backgroundColor: backgroundColorArray[0],
        },
      ];
    }

    return [];
  }, [
    ItemPhase,
    auth?.user?.role,
    backgroundColorArray,
    borderColorArray,
    device,
    graphData,
    sensor,
    userDevice,
  ]);

  useEffect(() => {
    setDataSets(computedDataSets);
  }, [computedDataSets]);

  // function get Graph data
  const getData = useCallback(async () => {
    if (!device?._id) return;

    try {
      const res = await POST(API.DEVICE.LATEST_DATA, {
        deviceId: device?._id,
        sensorName: sensor,
        deviceNumber: `${phasevalue - 1}`,
        startDate: startDate,
        endDate: startDate,
      });

      const data = res?.msg || [];

      setLabels([...new Set(data.map((item) => item.time))]);
      setGraphData(data);
    } catch (error) {
      console.error("getData error:", error);
      setLabels([]);
      setGraphData([]);
    }
  }, [device?._id, phasevalue, sensor, startDate]);

  useEffect(() => {
    if (value <= 0) return;
    getData();
  }, [getData, value]);

  useEffect(() => {
    if (value <= 0) return;
    intervalId.current = setInterval(() => {
      getData();
    }, 11000);
    return () => {
      clearInterval(intervalId.current);
    };
  }, [getData, intervalId, value]);

  React.useEffect(() => {
    if (dateType === 0) {
      setStartDate(moment(new Date()).format("YYYY-MM-DD"));
    }
  }, [dateType]);

  return (
    <>
      <Grid container className="graph-container mt-32 mb-40">
        <Grid
          container
          direction="row"
          justifyContent="space-between"
          alignItems="center"
          className="grapgh-head"
        >
          <Grid item md={6}>
            <Grid
              container
              direction="row"
              justifyContent="space-between"
              alignItems="center"
            >
              <Grid item>
                <Typography
                  align="center"
                  className="width100  white-typo ml-12"
                >
                  Device UID :{" "}
                  <span className="white-typo"> #{device?.nodeUid} </span>
                </Typography>
              </Grid>
              <Grid item>
                <Typography className="white-typo">
                  Device Name :
                  <span className="white-typo"> {device?.deviceName} </span>
                </Typography>
              </Grid>
            </Grid>
          </Grid>
          <Grid item md={6}>
            <Grid container justifyContent="space-between">
              <Typography></Typography>
              <Typography className="white-typo mt-8">
                Temperature :{" "}
                <span
                  className="red-typo"
                  style={{
                    backgroundColor: "#f7f8fd",
                    border: "2px solid #ffffff",
                    borderRadius: "6px",
                    padding: "1px",
                  }}
                >
                  {getTempValue({ msg: device }).toFixed(2)} °C
                </span>
              </Typography>
              <Typography className="white-typo mt-8 ">
                Humidity :{" "}
                <span className="white-typo">
                  {getHumValue({ msg: device }).toFixed(2)} %
                </span>
              </Typography>
              <DewnloadReport
                GraphDate={startDate}
                sensor={sensor}
                vmrSensors={phasevalue}
                device={device}
                DataSets={DataSets}
              />
            </Grid>
          </Grid>
        </Grid>
        <Grid
          container
          direction="row"
          justifyContent="space-between"
          className="mt-16  width100  "
        >
          <Grid item md={2} sx={{ marginLeft: "10px" }}>
            <FormControl
              className="MainPageFormControl mt10px grey-border "
              size="small"
            >
              {auth?.user?.role === 0 || auth?.user?.role === 1 ? (
                <TextField
                  select
                  variant="filled"
                  InputProps={{ disableUnderline: true }}
                  className="Selectdropstyle"
                  labelId="demo-select-small"
                  id="demo-select-small"
                  defaultValue={"RES"}
                  inputProps={{ "aria-label": "Without label" }}
                  onChange={(e) => {
                    SensorTypeChange(e.target.value);
                  }}
                >
                  <MenuItem value={"RES"} className="Selectmenustyle">
                    Resistance
                  </MenuItem>
                  <MenuItem value={"VMR"} className="Selectmenustyle">
                    Phase Meter
                  </MenuItem>
                  <MenuItem value={"NER"} className="Selectmenustyle">
                    GN
                  </MenuItem>
                  <MenuItem value={"SPD"} className="Selectmenustyle">
                    SPD
                  </MenuItem>{" "}
                  <MenuItem value={"TEMP"} className="Selectmenustyle">
                    Temperature
                  </MenuItem>
                  <MenuItem value={"HUM"} className="Selectmenustyle">
                    Humidity
                  </MenuItem>
                </TextField>
              ) : (
                <TextField
                  select
                  variant="filled"
                  InputProps={{ disableUnderline: true }}
                  className="Selectdropstyle"
                  labelId="demo-select-small"
                  id="demo-select-small"
                  defaultValue={"RES"}
                  inputProps={{ "aria-label": "Without label" }}
                  onChange={(e) => {
                    SensorTypeChange(e.target.value);
                  }}
                >
                  {userDevice?.resistanceNumber?.length > 0 ? (
                    <MenuItem value={"RES"} className="Selectmenustyle">
                      Resistance
                    </MenuItem>
                  ) : null}
                  {userDevice?.phaseNumber?.length > 0 ? (
                    <MenuItem value={"VMR"} className="Selectmenustyle">
                      Phase Meter
                    </MenuItem>
                  ) : null}
                  {userDevice?.gnNumber?.length > 0 ? (
                    <MenuItem value={"NER"} className="Selectmenustyle">
                      GN
                    </MenuItem>
                  ) : null}
                  {userDevice?.spdNumber?.length > 0 ? (
                    <MenuItem value={"SPD"} className="Selectmenustyle">
                      SPD
                    </MenuItem>
                  ) : null}
                  {userDevice?.temp?.length > 0 ? (
                    <MenuItem value={"TEMP"} className="Selectmenustyle">
                      Temperature
                    </MenuItem>
                  ) : null}
                  {userDevice?.humidity?.length > 0 ? (
                    <MenuItem value={"HUM"} className="Selectmenustyle">
                      Humidity
                    </MenuItem>
                  ) : null}
                </TextField>
              )}
            </FormControl>{" "}
          </Grid>
          <Grid item md={3}>
            {sensor === "VMR" ? (
              <>
                <FormControl
                  className="MainPageFormControl mt10px grey-border "
                  size="small"
                >
                  <TextField
                    select
                    variant="filled"
                    InputProps={{ disableUnderline: true }}
                    className="Selectdropstyle"
                    labelId="demo-select-small"
                    id="demo-select-small"
                    defaultValue={1}
                    inputProps={{ "aria-label": "Without label" }}
                    onChange={(e) => {
                      PhaseValueChange(e.target.value);
                    }}
                  >
                    {new Array(device.vmrSensor).map((item, i) => {
                      return (
                        <MenuItem
                          value={i + 1}
                          className="Selectmenustyle grey-border"
                        >
                          <Typography className="heading-black fs13px">
                            PH{i + 1}
                          </Typography>
                        </MenuItem>
                      );
                    })}
                  </TextField>
                </FormControl>{" "}
              </>
            ) : null}
          </Grid>
          <Grid item md={5} justifyContent="flex-end" alignItems="flex-end">
            <Typography align="right" className="mr-10 ">
              <LocalizationProvider dateAdapter={AdapterDateFns}>
                <DesktopDatePicker
                  className="rangepicker width-150"
                  InputProps={{
                    disableUnderline: true,
                  }}
                  inputFormat="dd/MM/yyyy"
                  value={startDate}
                  maxDate={currentDate}
                  onChange={(e) => {
                    handleData(e, "startDate");
                  }}
                  renderInput={(params) => (
                    <TextField
                      variant="filled"
                      className="width-100 rangepicker"
                      {...params}
                      inputProps={{
                        ...params.inputProps,
                        placeholder: "Start date",
                      }}
                    />
                  )}
                />
              </LocalizationProvider>
            </Typography>
          </Grid>
          {DataSets && DataSets?.length > 0 ? (
            <Line
              options={options}
              data={{
                labels,
                datasets: DataSets,
              }}
            />
          ) : (
            <Grid container justifyContent="center">
              <img src={hondaGif} alt="" />{" "}
            </Grid>
          )}
        </Grid>
      </Grid>
    </>
  );
}
